mapper.select:
SELECT
    d.*,
    e.name  AS elder_name,
    e.phone AS elder_phone
FROM device_info d
LEFT JOIN elder_profile e ON d.elder_id = e.id AND e.deleted = 0


        AND d.device_type = #{query.deviceType}


        AND d.status = #{query.status}


        AND d.online_status = #{query.onlineStatus}


        AND d.elder_id = #{query.elderId}


        AND (d.device_name LIKE CONCAT('%', #{query.keyword}, '%')
             OR d.device_no LIKE CONCAT('%', #{query.keyword}, '%'))


ORDER BY d.create_time DESC
